model.dbt_practice.agg_happiest_houses.raw_code:
{{ config(materialized='table') }}

-- Which haunted houses have the happiest visitors?
-- Grain: one row per haunted house

with feedback as (
    select * from {{ ref('stg_feedback__haunted_visitor_feedback') }}
    where satisfaction_rating >= {{ var('min_satisfaction_rating', 3) }}
)

select
    haunted_house_name,
    count(*)                                                as total_Visits,
    round(avg(satisfaction_rating), 2)                      as avg_Satisfaction,
    round(
        sum(case when would_recommend then 1 else 0 end)::numeric
        / nullif(count(*), 0) * 100, 2
    )                                                       as recommendation_rate,
    rank() over (
        order by avg(satisfaction_rating) desc, count(*) desc
    )                                                       as happiness_rank
from feedback
group by 1

model.dbt_practice.metricflow_time_spine.raw_code:
{{ config(materialized='table') }}

-- MetricFlow requires a time spine model with a single date_day column.
-- Used by dbt Semantic Layer / MetricFlow for time-series metric definitions.

with date_spine as (
    {{
        dbt_utils.date_spine(
            datepart   = "day",
            start_date = "cast('" ~ var('date_spine_start') ~ "' as date)",
            end_date   = "cast('" ~ var('date_spine_end')   ~ "' as date)"
        )
    }}
)

select
    date_day::date as date_day
from date_spine

macro.dbt_practice.generate_schema_name.macro_sql:
{% macro generate_schema_name(custom_schema_name, node) -%}

    {#-
        Behavior:
        - When DBT_PR_SCHEMA is set (dev PR builds), every model lands in
          that single ephemeral schema, e.g. PR_123_JDOE, regardless of any
          custom schema config in the model.
        - Otherwise, a model's custom schema config (e.g. `schema: marts`)
          is used AS-IS — no target-schema prefix concatenation. The
          environment is already distinguished by database (PROD_DB /
          STAGING_DB / DEV_DB), so re-encoding it into the schema name too
          just produces drift like PROD_MARTS vs MARTS vs PUBLIC_MARTS
          depending on who/what ran the build.
        - A model with NO custom schema config still falls back to
          target.schema, unchanged.
    -#}

    {%- set pr_schema = env_var('DBT_PR_SCHEMA', '') -%}

    {%- if pr_schema != '' -%}
        {{ pr_schema | trim }}

    {%- elif custom_schema_name is none -%}
        {{ target.schema }}

    {%- else -%}
        {{ custom_schema_name | trim }}

    {%- endif -%}

{%- endmacro %}

