model.dbt_project_evaluator.fct_source_d.raw_code:
-- Because we often work with multiple data sources, in our staging directory, we create one directory per source.

-- This model finds all cases where a source definition is NOT in the appropriate subdirectory.

{% set directory_pattern = get_directory_pattern() %}

with all_graph_resources as (
    select * from {{ ref('int_all_graph_resources') }}
    where is_excluded = cast(0 as {{ dbt.type_boolean() }})
),

-- find all sources that are definied in a .yml file NOT in their subdirectory
inappropriate_subdirectories_sources as (
    select 
        resource_name,
        resource_type,
        file_path as current_file_path,
        {{ dbt.concat(["'models" ~ directory_pattern ~ "'", "'" ~ var("staging_folder_name") ~ "'", "'" ~ directory_pattern ~ "'", 'source_name', "'" ~ directory_pattern ~ "'", 'file_name']) }} as change_file_path_to
    from all_graph_resources
    where resource_type = 'source'
    and directory_path not like {{ dbt.concat(["'%'", 'source_name', "'%'"]) }}
)

select * from inappropriate_subdirectories_sources

{{ filter_exceptions() }}

model.dbt_project_evaluator.fct_duplicat.raw_code:
with sources as (
    select
        resource_name,
        case 
            -- if you're using databricks but not the unity catalog, database will be null
            when {{ dbt_project_evaluator.quote_identifier('database') }} is NULL then {{ dbt.concat([dbt_project_evaluator.quote_identifier('schema'), "'.'", "identifier"]) }}
            else {{ dbt.concat([dbt_project_evaluator.quote_identifier('database'), "'.'", dbt_project_evaluator.quote_identifier('schema'), "'.'", "identifier"]) }}
        end as source_db_location 
    from {{ ref('int_all_graph_resources') }}
    where resource_type = 'source'
    and is_excluded = cast(0 as {{ dbt.type_boolean() }})
    {% if target.type not in ['fabric'] %}
    -- we order the CTE so that listagg returns values correctly sorted for some warehouses
    order by 1, 2
    {% endif %}
),

source_duplicates as (
    select
        source_db_location,
        {{ dbt.listagg(
            measure = 'resource_name',
            delimiter_text = "', '",
            order_by_clause = 'order by resource_name' if target.type in ['snowflake','redshift','duckdb','trino','fabric'])
        }} as source_names
    from sources
    group by source_db_location
    having count(*) > 1
)

select * from source_duplicates

{{ filter_exceptions() }}

